import re
import yaml

from pathlib import Path
from .section_epc import SectionEpc
from .section_base_stations import SectionBaseStations
from .section_ues import SectionUes
from .section_logs import SectionLogs
from .section_ws import SectionWs
from ..config_file_generic import ConfigFileGeneric
from ..utils.logger import logger


class COCO(ConfigFileGeneric):

    def __init__(self, filename='coco.yaml'):
        self._filename = filename
        self._file_content = {}
        self.updated_coco_yaml_content = ""
        self._sections = [
            SectionEpc(),
            SectionBaseStations(),
            SectionUes(),
            SectionLogs(),
            SectionWs(),
        ]

    def fetch_content(self, *args, **kwargs):
        for section in self._sections:
            self._file_content.update(section.generate_section_content(*args, **kwargs))
        coco_yaml_content = yaml.dump(self._file_content, default_flow_style=None)
        self.add_hardcode(coco_yaml_content)

    def add_hardcode(self, coco_yaml_content):
        # add hardcodes to final version coco.yaml due to lameness pyyaml library
        for line in coco_yaml_content.split("\n"):
            if re.search("mnc: (\\d+)", line):
                match = re.search("mnc: (\\d+)", line)
                line = line.replace(match.group(0), "mnc: '{}'".format(match.group(1)))
            plmn_regex = r'plmn: (\'(?:(?:\d+):(?:\d+),?)+\')'
            match = re.search(plmn_regex, line)
            if match:
                new_match = 'plmn: ' + match.group(1).replace(",", "','")
                line = re.sub(plmn_regex, new_match, line)

            self.updated_coco_yaml_content += line + "\n"

    def to_file(self, output_dir, *args, **kwargs):
        logger.info("Generating COCO.yaml")
        self.fetch_content(*args, **kwargs)
        filepath = Path(output_dir) / self._filename
        with open(filepath, mode='w', encoding='utf-8') as f:
            f.write(self.updated_coco_yaml_content)
